<?php
require_once 'config/functions.php';require_login();$id=(int)($_GET['id']??0);$uid=(int)current_user()['id_user'];
$s=$conn->prepare("SELECT * FROM pesanan WHERE id_pesanan=? AND id_user=?");$s->bind_param('ii',$id,$uid);$s->execute();$o=$s->get_result()->fetch_assoc();if(!$o)exit('Pesanan tidak ditemukan.');
$d=$conn->prepare("SELECT dp.*,p.nama_produk FROM detail_pesanan dp JOIN produk p ON p.id_produk=dp.id_produk WHERE dp.id_pesanan=?");$d->bind_param('i',$id);$d->execute();$items=$d->get_result();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail Pesanan</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-4"><a href="pesanan.php">← Kembali</a><div class="card p-4 mt-3"><h3>Pesanan #<?=$id?></h3><p>Status: <b><?=e($o['status'])?></b></p><p>Alamat: <?=nl2br(e($o['alamat_pengiriman']))?></p><table class="table"><thead><tr><th>Produk</th><th>Jumlah</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody><?php while($i=$items->fetch_assoc()):?><tr><td><?=e($i['nama_produk'])?></td><td><?=$i['jumlah']?></td><td><?=rupiah($i['harga'])?></td><td><?=rupiah($i['subtotal'])?></td></tr><?php endwhile;?></tbody></table><h4 class="text-primary">Total: <?=rupiah($o['total_harga'])?></h4></div></div></body></html>
